result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/app.py", "content": "import csv
import io
import sqlite3
from typing import Any

from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse, Response

DB_PATH = "orders.db"

app = FastAPI()


def get_connection() -> sqlite3.Connection:
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn


def seed_database() -> None:
    conn = sqlite3.connect(DB_PATH)
    cur = conn.cursor()
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS orders (
            id INTEGER PRIMARY KEY,
            customer TEXT NOT NULL,
            item TEXT NOT NULL,
            quantity INTEGER NOT NULL,
            total REAL NOT NULL
        )
        """
    )
    cur.execute("SELECT COUNT(*) FROM orders")
    if cur.fetchone()[0] == 0:
        # Note the deliberately tricky rows: one field contains a comma,
        # another contains quotes and a newline.
        cur.executemany(
            "INSERT INTO orders (id, customer, item, quantity, total) VALUES (?, ?, ?, ?, ?)",
            [
                (1, "Alice Johnson", "Mechanical Keyboard", 1, 129.99),
                (2, "Bob Smith", '17" Monitor, HDMI', 2, 359.98),
                (3, 'O"Brien, Patricia', "Desk Lamp", 1, 45.5),
                (4, "Dana White", "USB-C Cable\n(2m)", 5, 49.95),
            ],
        )
    conn.commit()
    conn.close()


@app.on_event("startup")
def on_startup() -> None:
    seed_database()


def fetch_orders() -> list[dict[str, Any]]:
    conn = get_connection()
    rows = conn.execute("SELECT * FROM orders ORDER BY id").fetchall()
    conn.close()
    return [dict(row) for row in rows]


def negotiate_format(accept_header: str | None) -> str | None:
    """Return 'json', 'csv', or None (unsupported).

    Missing header, */*, or any */* entry falls back to JSON.
    An explicit unsupported type yields None -> 406.
    """
    if not accept_header:
        return "json"
    has_wildcard = False
    for part in accept_header.split(","):
        media_type = part.split(";")[0].strip().lower()
        if not media_type:
            continue
        if media_type in ("*/*", "application/*"):
            has_wildcard = True
        elif media_type == "application/json":
            return "json"
        elif media_type == "text/csv":
            return "csv"
    if has_wildcard:
        return "json"
    return None


def render_csv(orders: list[dict[str, Any]]) -> str:
    if not orders:
        return ""
    buffer = io.StringIO()
    writer = csv.DictWriter(buffer, fieldnames=list(orders[0].keys()))
    writer.writeheader()
    writer.writerows(orders)
    return buffer.getvalue()


@app.get("/export/orders")
def export_orders(request: Request) -> Response:
    fmt = negotiate_format(request.headers.get("accept"))
    if fmt is None:
        return JSONResponse(
            status_code=406,
            content={
                "detail": (
                    "Not Acceptable: this endpoint supports only "
                    "application/json (default) and text/csv."
                )
            },
        )
    orders = fetch_orders()
    if fmt == "csv":
        return Response(
            content=render_csv(orders),
            media_type="text/csv",
            headers={"Content-Disposition": 'attachment; filename="orders.csv"'},
        )
    return JSONResponse(content=orders)
